  if (!Number.isSafeInteger(qty) || qty <= 0) throw new BizError(`商品 ${pid} 的数量必须为正安全整数：${qtyRaw}`);
  const sum = (merged.get(pid) ?? 0) + qty; // 同单同商品先合并
  if (!Number.isSafeInteger(sum)) throw new BizError(`商品 ${pid} 累计数量超出安全整数范围`);
  merged.set(pid, sum);
}

