      if (beforeFrom < qty)
        throw new BizError(`商品 ${pid} 调出仓 ${from} 余量不足（当前 ${beforeFrom}，需调拨 ${qty}），拒绝整单`);
      const afterFrom = beforeFrom - qty;
      const beforeTo = getStock(draft, pid, to);
